'use strict';
// Styled listboxes keep the existing form values as their single source of truth.
function enhanceDropdowns(){for(const select of document.querySelectorAll('select')){if(select.dataset.enhanced)continue;select.dataset.enhanced='true';const wrap=document.createElement('div');wrap.className='custom-select';select.before(wrap);wrap.append(select);select.hidden=true;select.setAttribute('aria-hidden','true');select.tabIndex=-1;const trigger=document.createElement('button'),menu=document.createElement('div');trigger.type='button';trigger.className='select-trigger';trigger.id=select.id+'-trigger';trigger.setAttribute('aria-haspopup','listbox');trigger.setAttribute('aria-expanded','false');const name=select.getAttribute('aria-label')||[...select.labels??[]].map(l=>l.textContent.trim()).join(' ')||select.id;trigger.setAttribute('aria-label',name);menu.id=select.id+'-menu';menu.className='select-menu';menu.setAttribute('role','listbox');menu.setAttribute('aria-label',name+' options');menu.hidden=true;trigger.setAttribute('aria-controls',menu.id);wrap.append(trigger,menu);let stamp='',focusIndex=0;
const close=()=>{menu.hidden=true;trigger.setAttribute('aria-expanded','false');};
const choose=i=>{const option=select.options[i];if(!option||option.disabled)return;select.value=option.value;select.dispatchEvent(new Event('change',{bubbles:true}));sync();close();trigger.focus();};
const sync=()=>{trigger.textContent=select.selectedOptions[0]?.textContent??'Choose…';trigger.disabled=select.disabled;const next=[...select.options].map(o=>o.value+'|'+o.textContent+'|'+o.disabled).join('\n');if(stamp!==next){stamp=next;menu.replaceChildren(...[...select.options].map((o,i)=>{const b=document.createElement('button');b.type='button';b.className='select-option';b.setAttribute('role','option');b.textContent=o.textContent;b.disabled=o.disabled;b.onclick=()=>choose(i);b.onkeydown=e=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();focusIndex=(i+(e.key==='ArrowDown'?1:-1)+select.options.length)%select.options.length;menu.children[focusIndex]?.focus();}if(e.key==='Escape'){e.preventDefault();close();trigger.focus();}if(e.key==='Tab')close();};return b;}));}for(let i=0;i<menu.children.length;i++)menu.children[i].setAttribute('aria-selected',String(i===select.selectedIndex));};
trigger.onclick=()=>{const open=menu.hidden;document.dispatchEvent(new CustomEvent('close-dropdowns'));sync();menu.hidden=!open;trigger.setAttribute('aria-expanded',String(open));if(open){focusIndex=Math.max(0,select.selectedIndex);menu.children[focusIndex]?.focus();}};trigger.onkeydown=e=>{if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();if(menu.hidden)trigger.click();}if(e.key==='Escape')close();};document.addEventListener('close-dropdowns',close);document.addEventListener('click',e=>{if(!wrap.contains(e.target))close();});select.addEventListener('change',sync);new MutationObserver(sync).observe(select,{childList:true,subtree:true,attributes:true,attributeFilter:['disabled','selected','label']});setInterval(sync,1000);sync();}}
enhanceDropdowns();
